let emails = $input.all().map((e, index) => {
  // Defensive extraction
  let from = e.json.from || e.json.From || e.json.sender || "Unknown";
  let subject = e.json.subject || e.json.Subject || "No Subject";
  let snippet = e.json.snippet || e.json.Snippet || "";

  // If it's a raw structure (headers array)
  if (from === "Unknown" && Array.isArray(e.json.payload?.headers)) {
    let fromHeader = e.json.payload.headers.find(h => h.name.toLowerCase() === 'from');
    let subjectHeader = e.json.payload.headers.find(h => h.name.toLowerCase() === 'subject');
    if (fromHeader) from = fromHeader.value;
    if (subjectHeader) subject = subjectHeader.value;
  }

  return `From: ${from}\nSubject: ${subject}\nSnippet: ${snippet}`;
}).join('\n\n---\n\n');

if (!emails || emails.trim() === "") {
  emails = "No emails found.";
}

let prompt = `You are an email assistant. Summarize the following inbox emails into a digest.

CLASSIFY ONLY the emails provided below. Do not invent emails. If "No emails found.", just output "📬 Inbox clear ✅"

🔴 VIP — julie.a.siegel84@gmail.com or jabentley9@gmail.com ONLY
🚨 IMPORTANT — VA, DOJ, IRS, OPM, court, banks, Charlotte school, medical, financial
🟡 MEDIUM — bills, subscriptions, receipts, newsletters
🗑️ SPAM — marketing, promotions, job alerts

Format EXACTLY like this (use Markdown). CRITICAL: KEEP THE ENTIRE RESPONSE CONCISE AND STRICTLY UNDER 3500 CHARACTERS TOTAL. If there are many medium/spam emails, truncate the list:

📬 *Email Digest*

🔴 *VIP*
• [From] — [Subject] — [1-line summary]
(or None.)

🚨 *Urgent / Important*
• [From] — [Subject] — [1-line summary]
(or None.)

🟡 *Medium*
• [From] — [Subject]
(or None.)

🗑️ *Likely Spam*
• [Comma separated senders]
(or None.)

Emails to classify:
${emails}`;

return [{ json: { prompt: prompt } }];

